test_purpose:
(1)

with { UE in 5GMM-DEREGISTERED/RRC-IDLE and UE finds a cell which provides access by NR NTN RAT }
ensure that {

   when { UE has no valid GNSS position }
       then { UE shall not establish RRC connection to perform a Registration procedure }
                     }

(2)

with { UE in 5GMM-DEREGISTERED/RRC-IDLE and UE finds a cell which provides access by NR NTN }
ensure that {

   when { Cell broadcasts SIB19 and UE has a valid GNSS position }
       then { UE establishes RRC connection and successfully performs Registration procedure}
                     }
